@router.post({{path}}, response_model=BatchRead, status_code=201)
async def create_batch(data: BatchCreate) -> BatchRead:
    """Create batch."""
    async def write(session: AsyncClientSession) -> BatchRead:
        """Write."""
        parent = await insert(Parent, model_values(data.parent), session)
        children = [await insert(Child, {"{{foreign_key}}": parent.id, **model_values(item)}, session) for item in data.children]
        return BatchRead.model_validate({"parent": parent, "children": children})
    return await transaction(write)
